import math
import random

random.seed(0)

def dist(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def train(embeddings, pairs, epochs=100, lr=0.05):
    for epoch in range(epochs):
        for w1, w2, similar in pairs:
            a = embeddings[w1]
            b = embeddings[w2]
            for i in range(len(a)):
                diff = a[i] - b[i]
                if similar:
                    a[i] -= lr * diff * 0.5
                    b[i] += lr * diff * 0.5
                else:
                    a[i] += lr * diff * 0.5
                    b[i] -= lr * diff * 0.5

emb = {
    "cat":    [0.5, -0.3],
    "kitten": [-0.4, 0.2],
    "fridge": [0.9, 0.8],
}

pairs = [
    ("cat", "kitten", True),
    ("cat", "fridge", False),
    ("kitten", "fridge", False),
]

train(emb, pairs, epochs=100, lr=0.1)

print("cat–kitten:", round(dist(emb["cat"], emb["kitten"]), 3))
print("cat–fridge:", round(dist(emb["cat"], emb["fridge"]), 3))
print("kitten–fridge:", round(dist(emb["kitten"], emb["fridge"]), 3))

